def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    horizontal = {
        r for r in range(h)
        if grid[r][0] == 1 and grid[r][w - 1] == 1
    }
    vertical = {
        c for c in range(w)
        if grid[0][c] == 1 and grid[h - 1][c] == 1
    }

    # Find original connected 2-regions. A region touched by a line
    # (including edge-adjacent cells) changes to color 1.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            region = []
            touched = False

            while stack:
                rr, cc = stack.pop()
                region.append((rr, cc))
                if any(abs(rr - line_r) <= 1 for line_r in horizontal):
                    touched = True
                if any(abs(cc - line_c) <= 1 for line_c in vertical):
                    touched = True

                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] == 2 and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            if touched:
                for rr, cc in region:
                    out[rr][cc] = 1

    for r in horizontal:
        for c in range(w):
            out[r][c] = 1
    for c in vertical:
        for r in range(h):
            out[r][c] = 1

    return out
